    private static SecretKey currentWrappingKey(SecretKey legacyKey) {
        byte[] encoded = legacyKey.getEncoded();
        try {
            return new SecretKeySpec(encoded, "AES");
        } finally {
            java.util.Arrays.fill(encoded, (byte) 0);
        }
    }
